python - <<'PY'
from pathlib import Path
import numpy as np

try:
    from trading.trading_io.prices import load_prices
    from trading.vk_qfeat import QFeatTape
except ModuleNotFoundError:
    from trading_io.prices import load_prices
    from vk_qfeat import QFeatTape

price_files = [
    Path('data/raw/stooq/btc.us.csv'),
    Path('data/raw/stooq/btc_intraday.csv'),
    Path('data/raw/stooq/btc_intraday_1s.csv'),
    Path('data/raw/stooq/btc_yf.csv'),
    Path('data/raw/yahoo/BTC_USD_1d.csv'),
]

tapes = [
    Path('logs/qfeat_btc.us_20260113_210153.memmap'),
    Path('logs/qfeat_btc_intraday_20260113_210153.memmap'),
    Path('logs/qfeat_btc_intraday_1s_20260113_210153.memmap'),
    Path('logs/qfeat_btc_yf_20260113_210153.memmap'),
    Path('logs/qfeat_BTC_USD_1d_20260113_210127.memmap'),
]

price_lengths = {}
for pf in price_files:
    try:
        prices, _vol, _ts = load_prices(pf, return_time=True)
        price_lengths[pf] = len(prices)
    except Exception as e:
        price_lengths[pf] = f"ERR:{e}"

print('Price lengths:')
for pf, ln in price_lengths.items():
    print(f"  {pf}: {ln}")

print('\nMatching tapes:')
for tape in tapes:
    for pf in price_files:
        ln = price_lengths[pf]
        if isinstance(ln, str):
            continue
        try:
            QFeatTape.from_existing(str(tape), rows=ln)
            print(f"  {tape} <-> {pf}")
        except Exception:
            pass
